use onklav_ui::{*,serde_json::{json,Value}};use std::{hint::black_box,time::{Instant,Duration}};
fn rss()->u64{std::fs::read_to_string("/proc/self/status").unwrap().lines().find(|s|s.starts_with("VmRSS:")).and_then(|s|s.split_whitespace().nth(1)).and_then(|s|s.parse().ok()).unwrap_or(0)}
fn main(){let mail=email::Mailbox::new("https://mail.example.org/jmap","a","inbox","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa").unwrap();let ids:Vec<_>=(0..20).map(|i|format!("e{i}")).collect();let rows:Vec<_>=ids.iter().map(|id|json!({"id":id,"subject":"Header café","from":[{"name":"Synthetic","email":"demo@example.org"}],"receivedAt":"2026-10-25T00:00:00Z"})).collect();let response=json!({"status":200,"text":json!({"methodResponses":[["Email/query",{"accountId":"a","position":0,"queryState":"q","ids":ids},"q"],["Email/get",{"accountId":"a","state":"s","list":rows,"notFound":[]},"g"]]}).to_string()});
let geo=maps_geo::Provider::new("https://route.example.org/route/v1","Synthetic route").unwrap();let coords:Vec<_>=(0..2048).map(|i|json!([-80.+i as f64/10000.,40.+i as f64/10000.])).collect();let route=json!({"status":200,"text":json!({"code":"Ok","routes":[{"distance":1000,"duration":100,"geometry":{"type":"LineString","coordinates":coords}}]}).to_string()});let place=weather::Place::open_meteo(40.,-80.,"Synthetic place").unwrap();let weather_response=json!({"status":200,"text":json!({"current_units":{"time":"unixtime","temperature_2m":"°C","wind_speed_10m":"km/h"},"current":{"time":10000,"temperature_2m":20,"wind_speed_10m":10,"weather_code":0}}).to_string()});let mut times:Vec<Vec<u64>>=vec![vec![],vec![],vec![]];let started=Instant::now();let mut memory=Vec::new();let mut iterations=0;
for batch in 0..7{for _ in 0..100{if started.elapsed()>Duration::from_secs(20){eprintln!("Workload self-deadline reached");std::process::exit(2)}let t=Instant::now();let page=email::page(&mail,&response,0).unwrap();let snapshot=email::merge(&Value::Null,&page).unwrap();assert_eq!(snapshot["items"].as_array().unwrap().len(),20);black_box(snapshot);if batch>0{times[0].push(t.elapsed().as_micros()as u64)}let t=Instant::now();let result=maps_geo::route_result(&geo,&route).unwrap();assert_eq!(result["points"].as_array().unwrap().len(),2048);black_box(result);if batch>0{times[1].push(t.elapsed().as_micros()as u64)}let t=Instant::now();let data=weather::parse(&place,&weather_response,10000).unwrap();black_box(weather::rows(&place,&data,true,Some(10000)));if batch>0{times[2].push(t.elapsed().as_micros()as u64)}if batch>0{iterations+=1}}
 memory.push(json!({"batch":batch,"rss_kib":rss()}));}
let names=["jmap20_header_parse_merge","geojson2048_route_parse","weather_parse_imperial_rows"];let mut stats=Vec::new();for(i,t)in times.iter_mut().enumerate(){t.sort_unstable();stats.push(json!({"operation":names[i],"samples":t.len(),"p50_us":t[t.len()/2],"p95_us":t[(t.len()*95/100).min(t.len()-1)],"max_us":t[t.len()-1]}));}println!("{}",json!({"profile":"optimized Linux host SDK only","warmup_iterations":100,"measured_iterations_per_operation":iterations,"elapsed_ms":started.elapsed().as_millis(),"timings":stats,"rss_samples":memory,"note":"Process RSS samples, not heap allocations or Android responsiveness; synthetic input reused; no network/native UI/carrier work"}));}
